        print("MISMATCH", g); bad += 1; break

# Odd wheels W_{2k+1}: center + odd cycle, 4-chromatic (not K4) -> no.
for k in range(2, 8):
    m = 2*k+1
    edges = [[0, i] for i in range(1, m+1)]
    for i in range(1, m+1):
        edges.append([i, i % m + 1])
    g = {"n": m+1, "edges": edges}
    ThreeColoring.validate(g)
    r = reduce(g); ThreeSat.validate(r)
    a, b = solve_three_coloring(g), solve_three_sat(r)
    if a != b:
        print("WHEEL MISMATCH", k, a, b); bad += 1
    if a is not False:
        print("wheel should be unsat", k)

# Even wheels are 3-colorable -> yes.
for k in range(2, 8):
    m = 2*k
    edges = [[0, i] for i in range(1, m+1)]
    for i in range(1, m+1):
        edges.append([i, i % m + 1])
    g = {"n": m+1, "edges": edges}
    r = reduce(g)
    a, b = solve_three_coloring(g), solve_three_sat(r)
    if a != b:
        print("EVEN WHEEL MISMATCH", k, a, b); bad += 1
    if a is not True:
        print("even wheel should be sat", k)

# Complete graphs K_n for n up to 8.
for n in range(0, 9):
    g = {"n": n, "edges": [[u,v] for u in range(n) for v in range(u+1,n)]}
    r = reduce(g)
    a, b = solve_three_coloring(g), solve_three_sat(r)
    exp = n <= 3
    if a != b or a != exp:
        print("K_n MISMATCH", n, a, b, exp); bad += 1

# Disconnected / empty-edge graphs.
for n in range(0, 10):
    g = {"n": n, "edges": []}
    r = reduce(g)
    if solve_three_coloring(g) != solve_three_sat(r):
        print("EMPTY MISMATCH", n); bad += 1

print("stress done, bad =", bad)
