"""Independent tests for reduce.py: 3-Coloring -> 3-SAT.

We implement our own brute-force solvers from the problem definitions in
problems.py, then compare solver answers on many small source instances and
their reductions.  We also validate every produced target instance.
"""

from __future__ import annotations

import itertools
import random

from problems import SOURCE, TARGET
import reduce as reduce_module


# ----------------------------------------------------------------------
# Brute-force solver for 3-Coloring (backtracking, exhaustive)
# ----------------------------------------------------------------------

def solve_three_coloring(instance: dict) -> bool:
    n = instance["n"]
    adj = [[] for _ in range(n)]
    for u, v in instance["edges"]:
        adj[u].append(v)
        adj[v].append(u)
    color = [-1] * n

    def bt(i: int) -> bool:
        if i == n:
            return True
        for c in range(3):
            if all(color[j] != c for j in adj[i]):
                color[i] = c
                if bt(i + 1):
                    return True
                color[i] = -1
        return False

    return bt(0)


# ----------------------------------------------------------------------
# Brute-force solver for 3-SAT (DPLL with unit propagation, exhaustive)
# ----------------------------------------------------------------------

def solve_three_sat(instance: dict) -> bool:
    clauses = [tuple(c) for c in instance["clauses"]]

    def dpll(clauses, assignment):
        # Unit propagation / clause simplification loop.
        clauses = [list(c) for c in clauses]
        while True:
            new_clauses = []
